import json,re,datetime
try:
    turn_snapshot=None
    s=json.loads(vars.get('state','{}'))
    today=datetime.date.fromisoformat(str(vars['now'])[:10])
    holidays={'2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01'}
    def business(d): return d.weekday()<5 and d.isoformat() not in holidays
    def forward(d):
        while not business(d): d+=datetime.timedelta(days=1)
        return d
    def after(n):
        d=today
        while n:
            d+=datetime.timedelta(days=1)
            if business(d): n-=1
        return d
    def dateval(t):
        t=str(t).strip().lower()
        if any(c in t for c in ('"','[',']','{','}','|','\\')) or not t: raise ValueError('complete date token')
        if t.endswith('...'): raise ValueError('unfinished date')
        t=re.sub(r'(\d)(st|nd|rd|th)\b',r'\1',t)
        t=re.sub(r'\s+',' ',t.replace(',',' ')).strip().rstrip('.')
        if not re.fullmatch(r'[a-z0-9 /-]+',t): raise ValueError('date token')
        if t=='today': return today
        if t=='tomorrow': return today+datetime.timedelta(days=1)
        weekdays=['monday','tuesday','wednesday','thursday','friday','saturday','sunday']
        months=['january','february','march','april','may','june','july','august','september','october','november','december']
        m=re.match(r'^(?:(next|this) )?('+'|'.join(weekdays)+r')(?: |$)',t)
        relative=None
        if m:
            weekday=weekdays.index(m[2]); mode=m[1]
            relative=today-datetime.timedelta(days=today.weekday())+datetime.timedelta(days=weekday+(7 if mode=='next' else 0))
            t=t[m.end():].strip()
            if not t: return relative
        explicit=None
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}',t): explicit=datetime.date.fromisoformat(t)
        elif re.fullmatch(r'\d{1,2}[/-]\d{1,2}[/-]\d{4}',t):
            a,b,c=re.split(r'[/-]',t); explicit=datetime.date(int(c),int(b),int(a))
        else:
            natural=re.fullmatch(r'(\d{1,2}) ([a-z]+)(?: (\d{4}))?',t)
            if natural and natural[2] in months: explicit=datetime.date(int(natural[3] or today.year),months.index(natural[2])+1,int(natural[1]))
            if explicit is None:
                words=re.fullmatch(r'([a-z -]+) ('+'|'.join(months)+r')(?: (\d{4}))?',t)
                if words: explicit=datetime.date(int(words[3] or today.year),months.index(words[2])+1,spoken_number(words[1]))
            if explicit is None:
                monthfirst=re.fullmatch(r'('+'|'.join(months)+r') ([a-z0-9 -]+?)(?: (\d{4}))?',t)
                if monthfirst: explicit=datetime.date(int(monthfirst[3] or today.year),months.index(monthfirst[1])+1,spoken_number(monthfirst[2]))
            if explicit is None and m and re.fullmatch(r'\d{1,2}',t):
                explicit=datetime.date(today.year,today.month,int(t))
        if m:
            if explicit is None or explicit.weekday()!=weekday or (mode and explicit!=relative): raise ValueError('inconsistent complete date')
        if explicit is None and re.fullmatch(r'(?:the )?(?:\d{1,2}|(?:twenty[ -]|thirty[ -])?(?:first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|thirtieth))',t):
            try:
                day=spoken_number(re.sub(r'^the ','',t))
                offers=[p['offer'] for p in s.get('products',[]) if p.get('offer',{}).get('spoken') and p['product_id']==s.get('current')]
                if len(offers)==1 and datetime.date.fromisoformat(offers[0]['date']).day==day: explicit=datetime.date.fromisoformat(offers[0]['date'])
                elif 1<=day<=31: raise ValueError('day conflicts with current offer')
            except ValueError: raise
        if explicit is None and re.search(r'\d|monday|tuesday|wednesday|thursday|friday|saturday|sunday',t): raise ValueError('unfinished date')
        if explicit is None and not re.fullmatch(r'next week|end of (?:the )?month|when my salary comes|later|soon',t): raise ValueError('invalid date expression')
        return explicit
    def spoken_number(text):
        text=str(text).lower().replace('-',' ').replace(',',' ')
        if text.strip().isdigit(): return int(text.strip())
        units=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen']
        tens={'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,'seventy':70,'eighty':80,'ninety':90}
        ordinals={'first':'one','second':'two','third':'three','fourth':'four','fifth':'five','sixth':'six','seventh':'seven','eighth':'eight','ninth':'nine','tenth':'ten','eleventh':'eleven','twelfth':'twelve','thirteenth':'thirteen','fourteenth':'fourteen','fifteenth':'fifteen','sixteenth':'sixteen','seventeenth':'seventeen','eighteenth':'eighteen','nineteenth':'nineteen','twentieth':'twenty','thirtieth':'thirty'}
        total=0; part=0
        for token in text.split():
            token=ordinals.get(token,token)
            if token=='and': continue
            if token in units: part+=units.index(token)
            elif token in tens: part+=tens[token]
            elif token=='hundred': part*=100
            elif token=='thousand': total+=part*1000; part=0
            else: raise ValueError('number words')
        return total+part
    def normalize_text(text):
        text=str(text).lower().replace("’","'").replace("‘","'").replace("ʼ","'")
        for separator in ('‐','‑','‒','–','—','−'): text=text.replace(separator,'-')
        return re.sub(r'\s+',' ',text).strip()
    def self_answer(text):
        text=normalize_text(text)
        # Independent questions cannot supply missing digits, day, month or year.
        question=re.search(r'(?:\b(?:and|but)\s+)?\b(?:why|what|are you|is this|can you explain|could you explain|would a relative|could my|can my|if my|suppose|hypothetically)\b',text)
        if question: text=text[:question.start()].rstrip(' ,;.!?')
        if any(ch in text for ch in ('"','“','”','[',']','{','}','...')): return ''
        if re.search(r"\b(?:not|never|if|would|could|his|her|their|mother|father|quoted|diary)\b",text): return ''
        return text.rstrip(' .;,!?')
    def word_year(text):
        text=normalize_text(text).replace('-',' ')
        text=re.sub(r'\s+',' ',text).strip()
        if re.fullmatch(r'\d{4}',text): return int(text)
        units='zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen'.split()
        tens={'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,'seventy':70,'eighty':80,'ninety':90}
        def under100(t):
            z=t.split()
            if len(z)==1 and z[0] in units: return units.index(z[0])
            if len(z)==1 and z[0] in tens: return tens[z[0]]
            if len(z)==2 and z[0] in tens and z[1] in units[1:10]: return tens[z[0]]+units.index(z[1])
            if len(z)==2 and z[0] in ('oh','zero') and z[1] in units[1:10]: return units.index(z[1])
            raise ValueError('incomplete or unsupported year operand')
        m=re.fullmatch(r'(eighteen|nineteen|twenty) (.+)',text)
        if m and 'thousand' not in m[2]:
            century={'eighteen':1800,'nineteen':1900,'twenty':2000}[m[1]]
            suffix=m[2]
            if suffix=='hundred': return century
            suffix=re.sub(r'^hundred (?:and )?','',suffix)
            return century+under100(suffix)
        m=re.fullmatch(r'(one|two) thousand(?: (?:and )?(.+))?',text)
        if m: return (1000 if m[1]=='one' else 2000)+(under100(m[2]) if m[2] else 0)
        raise ValueError('complete explicit year required')
    def security_raw(text,phase):
        text=self_answer(text)
        if not text: return ''
        if phase=='phone':
            text=re.sub(r"^(?:my (?:phone(?: number)?(?: ends in)?|last four(?: digits)?) (?:is|are) |(?:the )?last four(?: digits)?(?: of (?:my|the) phone(?: number)?)? (?:is|are) |it is |it's |they are |the digits are )",'',text)
            digits={'zero':'0','oh':'0','one':'1','two':'2','three':'3','four':'4','five':'5','six':'6','seven':'7','eight':'8','nine':'9'}
            tokens=text.replace('-',' ').split()
            if len(tokens)==4 and all(t in digits for t in tokens): return ''.join(digits[t] for t in tokens)
            return text if re.fullmatch(r'\d{4}',text) else ''
        text=re.sub(r"^(?:my (?:date of birth|birth date|birthday|dob) is |(?:the )?date of birth is |i was born (?:on |in )?|i was born: |it is |it's |the )",'',text)
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}',text): return datetime.date.fromisoformat(text).isoformat()
        if re.fullmatch(r'\d{1,2}[ ./-]\d{1,2}[ ./-]\d{4}',text):
            day,month,year=re.split(r'[ ./-]',text); return datetime.date(int(year),int(month),int(day)).isoformat()
        months='january february march april may june july august september october november december'.split()
        text=text.replace(',',' ')
        text=re.sub(r'\bday of (?:the )?(?:month of )?', '',text)
        text=re.sub(r'\b(?:in (?:the )?year|in the year|of the year)\s+', '',text)
        text=re.sub(r'\s+',' ',text).strip()
        for i,month in enumerate(months):
            if re.search(r'\b'+month+r'\b',text):
                day,year=text.split(month,1)
                if not day.strip():
                    m=re.fullmatch(r' ([a-z]+(?:[- ](?:first|second|third|fourth|fifth|sixth|seventh|eighth|ninth))?|\d{1,2}(?:st|nd|rd|th)?) (.+)',year)
                    if not m: return ''
                    day,year=m[1],m[2]
                day=re.sub(r'^(?:the )?','',day.strip()); day=re.sub(r'\s+of$','',day)
                day=re.sub(r'(\d)(st|nd|rd|th)\b',r'\1',day)
                if not re.fullmatch(r'\d{1,2}|[a-z]+(?:[- ][a-z]+)?',day): return ''
                return datetime.date(word_year(year.strip()),i+1,spoken_number(day)).isoformat()
        return ''
    def recipient_reply(text):
        text=normalize_text(text)
        if any(x in text for x in ('"','“','”','[',']','{','}','...')): return False
        # Strip only independent trailing questions, across punctuation boundaries.
        text=re.split(r'(?:[,;!?]|(?<!mr)(?<!ms)(?<!dr)\.)\s*(?:and\s+)?(?=(?:are you|is this|why|what|can you explain|could you explain)\b)',text,1)[0]
        text=re.sub(r'\b(mr|ms|mrs|dr)\.',r'\1',text)
        text=re.sub(r'[.!?]+$','',text).strip()
        text=re.sub(r'\s+',' ',text)
        text=re.sub(r'^(?:hello|hi|good morning|good afternoon)[,; ]*','',text)
        text=re.sub(r'^(?:yes|speaking)[,; ]+','',text)
        if text in ('yes',"that's me",'that is me','speaking','yes speaking',"yes, speaking",'this is me'): return True
        first=normalize_text(vars.get('first_name',''))
        last=normalize_text(vars.get('last_name',''))
        title=normalize_text(vars.get('title','')).rstrip('.')
        names=set()
        if first and last: names.add(first+' '+last)
        if last and title: names.add(title+' '+last)
        if first: names.add(first)
        if last: names.add(last)
        text=re.sub(r'^(?:this is|i am|i\x27m)\s+','',text)
        text=re.sub(r'[,; ]+speaking$','',text)
        return text in names
    def minor_units(value):
        token=str(value)
        if not re.fullmatch(r'\d+(?:\.\d+)?',token): raise ValueError('API monetary grammar')
        whole,separator,fraction=token.partition('.')
        if any(d!='0' for d in fraction[2:]): raise ValueError('monetary precision')
        return int(whole)*100+int((fraction+'00')[:2])
    def amountval(token):
        token=str(token)
        if not re.fullmatch(r'\d+(?:\.\d{1,2})?',token): raise ValueError('amount grammar')
        value=float(token)
        if not 0<=value<float('inf'): raise ValueError('nonfinite amount')
        return value
    def asserted(e,text,unfinished):
        if e['c']!='1': return False
        acts={'deceased':r"\b(?:died|dead|deceased|passed away)\b",'wrong_number':r"\b(?:wrong number|does not belong|doesn't belong|not (?:his|her|their) number)\b",'human':r"\b(?:human|person|agent|representative)\b",'plan':r"\b(?:plan|lower instalments|lower installments|restructur)\w*",'hardship':r"\b(?:ill|sick|illness|job loss|lost (?:my |the )?job|death in (?:the |my )?family)\b",'stop':r"\b(?:do not contact|don't contact|stop|do not want to talk|don't want to talk|do not wish to talk|don't wish to talk|leave me alone)\b",'third':r"\b(?:not me|not (?:him|her)|relative|wife|husband|mother|father|sister|brother|not here|not available)\b"}
        if e['k'] not in acts: return True
        negatives={'deceased':r"\b(?:not dead|not deceased|has not died|hasn't died|did not die|didn't die)\b",'wrong_number':r"\b(?:not the wrong number|is not a wrong number)\b",'human':r"\b(?:do not|don't|not) want (?:a )?(?:human|person|agent)\b",'plan':r"\b(?:do not|don't|not) want (?:a )?(?:new )?(?:plan|lower instalments)\b",'hardship':r"\b(?:not ill|not sick|did not lose|haven't lost)\b",'stop':r"\b(?:do not|don't) want to stop\b"}
        # Each act is checked against its own raw clause, including quoted spans.
        text=text.replace("’", "'").replace("‘", "'")
        text=re.sub(r'\bif (?:you (?:need|want) to know|that helps|you must know)\s*[,;:]?', '', text)
        clauses=re.split(r'(?<!\.)[.!?;](?!\.)|,\s*(?:but|and|(?=if\b))\s*|\s+(?:but|and)\s+(?=if\b)',text)
        for clause in clauses:
            if not re.search(acts[e['k']],clause): continue
            if re.search(r'["“”]|\b(?:if|hypothetically|suppose|quoted|quoting)\b',clause): continue
            if re.search(r'\b(?:would|could)\b',clause) and not re.search(r'\b(?:could|would) (?:you|i|someone) (?:please )?(?:speak|talk|connect|transfer|help|get|arrange|put|offer|lower)',clause): continue
            if e['k']=='deceased' and re.search(r'\b(?:my|our|his|her) (?:mother|father|sister|brother|wife|husband|relative|grandmother|grandfather)\b',clause): continue
            if re.search(negatives.get(e['k'],r'(?!)'),clause): continue
            if re.search(r'\.\.\.\s*$|\b(?:but|and|for|or|actually|instead|wait|correction|on|next|this|hundred)\s*$',clause): continue
            return True
        return False
    def decode(text):
        if not isinstance(text,str) or len(text)>4000: raise ValueError('event bound')
        if text!=text.strip() or not text.endswith('\nEND'): raise ValueError('exact terminal')
        lines=text.splitlines()
        if len(lines)>17: raise ValueError('row bound')
        if not lines or lines[-1]!='END': raise ValueError('terminal')
        out=[]
        for row in lines[:-1]:
            d={}
            for part in row.split('|'):
                if part.count('=')!=1: raise ValueError('separator')
                k,v=part.split('=',1)
                if k not in ('k','p','a','d','c','v','t','scope','u','q','x','sub','claim','pol','mode') or k in d or not v: raise ValueError('tag')
                if any(x in v for x in ('[',']','{','}','"','\\')): raise ValueError('fragment')
                d[k]=v
            if not set(('k','c')).issubset(d) or d['c'] not in ('0','1'): raise ValueError('completion')
            if d['k'] not in ('yes','accept','confirm','answer','proposal','no','vague','too_much','paid','dispute','partial','third','wrong_number','deceased','callback','decline','human','plan','hardship','stop','unknown','question','consent'): raise ValueError('kind')
            if 'a' in d and not re.fullmatch(r'\d+(?:\.\d{1,2})?|full|total:\d+(?:\.\d{1,2})?',d['a']): raise ValueError('amount')
            if 'a' in d and d['a']!='full': amountval(d['a'][6:] if d['a'].startswith('total:') else d['a'])
            if d.get('u','') not in ('','amount','date','both','unknown','answer'): raise ValueError('component')
            if 'scope' in d and d['scope']!='current': raise ValueError('scope')
            if d['c']=='1' and 'u' in d: raise ValueError('complete with unfinished component')
            # An explicitly unfinished date is a fragment, never an eligible date.
            # Validate the whole row's syntax first, then its independently complete facts.
            unfinished_date=d['c']=='0' and d.get('u') in ('date','both','unknown')
            if 'd' in d and not unfinished_date:
                try: dateval(d['d'])
                except Exception: raise ValueError('date for '+d.get('p','current product'))
            if 'x' in d and len(d['x'])>240: raise ValueError('clause bound')
            for tag,allowed in (('sub',('self','other','unknown')),('claim',('current_bank','historical_bank','unrelated','unknown')),('pol',('positive','negative','unknown')),('mode',('asserted','quoted','hypothetical','unknown'))):
                if tag in d and d[tag] not in allowed: raise ValueError('claim qualifier')

            if d['k']=='question' and d.get('q') not in ('ai','scam','purpose','security','balance','offer','readback','relative','unknown'): raise ValueError('question')
            if d['k']=='consent' and d.get('v') not in ('pause','withdraw','readback'): raise ValueError('consent description')
            if 'q' in d and d['k']!='question': raise ValueError('question scope')
            out.append(d)
        if not out: raise ValueError('empty')
        return out
    def resolve(ref):
        if ref in ('all','everything'): return s['products']
        refs=str(ref).split(','); out=[]
        for r in refs:
            r=r.strip().lower().replace('_',' ')
            matches=[p for p in s['products'] if r in (p['product_id'].lower().replace('_',' '),p['type'].replace('_',' '),p['label'].lower())]
            if len(matches)!=1: raise ValueError('reference')
            if matches[0] not in out: out.append(matches[0])
        return out
    def bank_claim(e,raw):
        if e.get('c')!='1' or e.get('sub')!='self' or e.get('pol')!='positive' or e.get('mode')!='asserted': return False
        if e.get('claim') not in ('current_bank','historical_bank'): return False
        if e['k']=='paid' and e.get('claim')!='current_bank': return False
        span=normalize_text(e.get('x',''))
        source=normalize_text(raw)
        if not span or source.count(span)!=1: return False
        start=source.index(span); end=start+len(span)
        # Span cannot borrow an assertion from quoted source text or a conditional clause.
        quoted=False
        for char in source[:start]:
            if char in ('"','“','”'): quoted=not quoted
        if quoted or any(ch in span for ch in ('"','“','”')) or (source[:start].rstrip().endswith("'") and source[end:].lstrip().startswith("'")): return False
        boundary=max(source.rfind(';',0,start),source.rfind('.',0,start),source.rfind('?',0,start))
        context=source[boundary+1:end]
        if re.search(r"\b(?:if|suppose|hypothetically|quoted|quoting|diary|parcel|invoice|purchase|shopping|receipt label|note says|snippet|label|(?:brother|sister|wife|husband|friend|someone) (?:said|says|wrote))\b",context): return False
        span=re.sub(r"\bi've\b",'i have',span)
        refs=resolve(e.get('p','all' if s.get('initial') else s.get('current','')))
        # Extend to the entire current assertion so a cropped producer span cannot
        # hide an exclusion. Independent current negative target clauses override it.
        act=source[start:]
        act=re.split(r'(?<!\.)[.!?](?!\.)',act,1)[0]
        def mentions(text):
            return set(p['product_id'] for p in s['products'] if any(re.search(r'\b'+re.escape(label)+r'\b',text) for label in (normalize_text(p['label']),p['type'].replace('_',' '))))
        positive_span=span
        negative=set()
        exclusions=list(re.finditer(r"\b(?:except(?: for)?|excluding|apart from|other than|but not)\b",act))
        if exclusions:
            cut=exclusions[0].start()
            positive_span=act[:cut]
            for i,marker in enumerate(exclusions):
                tail=act[marker.end():exclusions[i+1].start() if i+1<len(exclusions) else len(act)].strip(' ,;:')
                tail=re.split(r';|,?\s+(?:and|but)\s+i\b|,\s*i\b',tail,1)[0].strip()
                # Unknown or unfinished exclusion never expands a collective claim.
                ids=mentions(tail)
                if not ids or re.search(r'\.\.\.|\b(?:and|or|the|my|a|except|excluding)\s*$',tail): return False
                remainder=tail
                for product in s['products']:
                    for label in sorted((normalize_text(product['label']),product['type'].replace('_',' ')),key=len,reverse=True):
                        remainder=re.sub(r'\b'+re.escape(label)+r'\b',' ',remainder)
                remainder=re.sub(r'\b(?:my|the|and|or|also|only)\b|[,() ]','',remainder)
                if remainder: return False
                negative.update(ids)
        # Scan complete source clauses for contradictory named decisions; quoted
        # and hypothetical clauses have no authority in either direction.
        unquoted=re.sub(r'"[^"\n]*"|“[^”\n]*”', '',source)
        clauses=re.split(r';|(?<!\.)[.!?](?!\.)|,?\s+but\s+|,?\s+and\s+(?=(?:i |my |the ))',unquoted)
        negpattern=r"\b(?:did not pay|didn't pay|have not paid|haven't paid|has not been paid|was not paid|is not paid|not paid|never paid|not yet paid|did not dispute|don't dispute|do not dispute|is mine|belongs to me)\b"
        for clause in clauses:
            if re.search(r'\b(?:if|suppose|hypothetically|quoted|quoting|said|says|wrote)\b',clause): continue
            if re.search(negpattern,clause):
                ids=mentions(clause)
                if ids: negative.update(ids)
                elif clause in act or clause.strip() in span: return False
            for product in s['products']:
                for label in (normalize_text(product['label']),product['type'].replace('_',' ')):
                    if re.search(r'\bnot (?:my |the )?'+re.escape(label)+r'\b',clause): negative.add(product['product_id'])
        if any(p['product_id'] in negative for p in refs): return False
        if re.search(r"\b(?:might|maybe|would|could)\b",positive_span): return False
        named=mentions(positive_span)
        collective=bool(re.search(r"\b(?:all (?:of )?(?:my |the |these |our )?(?:bank )?(?:products|accounts|debts|loans|payments)|all of them|all these payments|everything)\b",positive_span))
        if collective and re.search(r'\bloans\b',positive_span) and not re.search(r'\b(?:products|accounts|debts|payments|everything|all of them)\b',positive_span):
            collective=all(p['type'] in ('personal_loan','car_loan') for p in refs)
        explicit=all(p['product_id'] in named for p in refs)
        if named and not explicit and not collective: return False
        current=bool(re.search(r"\b(?:arrears|past[- ]due|late payment|this (?:payment|debt|amount|product))\b",span)) and len(refs)==1 and refs[0]['product_id']==s.get('current')
        bare=bool(re.fullmatch(r"i (?:have |had )?(?:already )?(?:paid|made (?:the |this |that )?payment)(?: already)?[ .!]*",span)) and len(refs)==1 and (len(s['products'])==1 or refs[0]['product_id']==s.get('current') and not s.get('initial'))
        current=current or collective
        if e['k']=='paid':
            if re.search(r'\b(?:paid off|closed|used to|years ago|in the past)\b',span): return False
            positive=re.search(r"\bi (?:have |had )?(?:already )?(?:paid|made (?:the |this |that )?payment)\b",positive_span)
            return bool(positive and (explicit or current or bare))
